// Extract the generated message from Claude response
const response = $input.first().json;
const message = response.content[0].text;

// Random delay between 45 and 120 seconds
const delaySeconds = Math.floor(Math.random() * (120 - 45 + 1)) + 45;

// Also pass through the original prospect data
const prospect = $('Split In Batches').first().json;

return [{
  json: {
    ...prospect,
    generated_message: message,
    delay_seconds: delaySeconds
  }
}];

// Navigate to the prospect's profile and send the connection invite
const profileUrl = $input.first().json.profile_url;
const message = $input.first().json.generated_message;
const prospectId = $input.first().json.id;

// Log the action for audit
return [{
  json: {
    prospect_id: prospectId,
    profile_url: profileUrl,
    message_sent: message,
    action: 'connection_invite_sent',
    sent_at: new Date().toISOString(),
    status: 'sent'
  }
}];

// Check remaining daily quota
const maxDailyInvites = 100;
const today = new Date().toISOString().split('T')[0];

// Count invites sent today
const todayCount = 0; // Would be queried from DB in production

const remaining = maxDailyInvites - todayCount;

return [{
  json: {
    daily_quota_max: maxDailyInvites,
    daily_sent: todayCount,
    daily_remaining: remaining,
    quota_exceeded: remaining <= 0,
    should_pause: remaining <= 5
  }
}];

